1	package oci
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/http"
8		"net/http/httptest"
9		"testing"
10	)
11	
12	// These tests pin the typed errors of DEVDESK-298 (IS-18 criterion 1): a
13	// non-success status from the registry or the token endpoint is a
14	// *StatusError, and Error() keeps today's strings character for character.
15	
16	func TestListRegistryTagsStatusError(t *testing.T) {
17		tests := []struct {
18			name          string
19			code          int
20			challenge     string
21			wantChallenge string
22			wantMsg       string
23		}{
24			{"401 without challenge", 401, "", "", "unexpected auth challenge: "},
25			{"401 basic challenge", 401, `Basic realm="x"`, `Basic realm="x"`, `unexpected auth challenge: Basic realm="x"`},
26			{"403", 403, "", "", "registry returned 403"},
27			{"404", 404, "", "", "registry returned 404"},
28			{"405", 405, "", "", "registry returned 405"},
29			{"429", 429, "", "", "registry returned 429"},
30			{"500", 500, "", "", "registry returned 500"},
31		}
32		for _, tt := range tests {
33			t.Run(tt.name, func(t *testing.T) {
34				srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
35					if tt.challenge != "" {
36						w.Header().Set("Www-Authenticate", tt.challenge)
37					}
38					w.WriteHeader(tt.code)
39				}))
40				defer srv.Close()
41	
42				_, err := ListRegistryTags(srv.URL, "library/alpine", "", "")
43				var se *StatusError
44				if !errors.As(err, &se) {
45					t.Fatalf("err = %v (%T), want a *StatusError", err, err)
46				}
47				if se.Code != tt.code {
48					t.Errorf("Code = %d, want %d", se.Code, tt.code)
49				}
50				if se.Source != SourceRegistry {
51					t.Errorf("Source = %v, want SourceRegistry", se.Source)
52				}
53				if se.Challenge != tt.wantChallenge {
54					t.Errorf("Challenge = %q, want %q", se.Challenge, tt.wantChallenge)
55				}
56				if got := err.Error(); got != tt.wantMsg {
57					t.Errorf("Error() = %q, want %q", got, tt.wantMsg)
58				}
59			})
60		}
61	}
62	
63	func TestListRegistryTagsTokenEndpointStatusError(t *testing.T) {
64		for _, code := range []int{401, 403, 500} {
65			t.Run(fmt.Sprint(code), func(t *testing.T) {
66				var srv *httptest.Server
67				srv = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
68					if r.URL.Path == "/token" {
69						w.WriteHeader(code)
70						return
71					}
72					w.Header().Set("Www-Authenticate", fmt.Sprintf(`Bearer realm="%s/token",service="reg"`, srv.URL))
73					w.WriteHeader(http.StatusUnauthorized)
74				}))
75				defer srv.Close()
76	
77				_, err := ListRegistryTags(srv.URL, "library/alpine", "", "")
78				var se *StatusError
79				if !errors.As(err, &se) {
80					t.Fatalf("err = %v (%T), want a *StatusError", err, err)
81				}
82				if se.Code != code {
83					t.Errorf("Code = %d, want %d", se.Code, code)
84				}
85				if se.Source != SourceToken {
86					t.Errorf("Source = %v, want SourceToken", se.Source)
87				}
88				if se.Challenge != "" {
89					t.Errorf("Challenge = %q, want empty", se.Challenge)
90				}
91				if want := fmt.Sprintf("token endpoint returned %d", code); err.Error() != want {
92					t.Errorf("Error() = %q, want %q", err.Error(), want)
93				}
94			})
95		}
96	}
