98	// Failures that are not a status stay plain errors: a caller must not read a
99	// missing realm or a bad body as an HTTP verdict.
100	func TestListRegistryTagsNonStatusErrorsAreNotStatusErrors(t *testing.T) {
101		tests := []struct {
102			name    string
103			handler func(srv **httptest.Server) http.HandlerFunc
104		}{
105			{"undecodable tags body", func(_ **httptest.Server) http.HandlerFunc {
106				return func(w http.ResponseWriter, _ *http.Request) { _, _ = w.Write([]byte("not json")) }
107			}},
108			{"bearer challenge missing realm", func(_ **httptest.Server) http.HandlerFunc {
109				return func(w http.ResponseWriter, _ *http.Request) {
110					w.Header().Set("Www-Authenticate", `Bearer service="reg"`)
111					w.WriteHeader(http.StatusUnauthorized)
112				}
113			}},
114			{"token response without token", func(srv **httptest.Server) http.HandlerFunc {
115				return func(w http.ResponseWriter, r *http.Request) {
116					if r.URL.Path == "/token" {
117						_, _ = w.Write([]byte(`{}`))
118						return
119					}
120					w.Header().Set("Www-Authenticate", fmt.Sprintf(`Bearer realm="%s/token"`, (*srv).URL))
121					w.WriteHeader(http.StatusUnauthorized)
122				}
123			}},
124			{"undecodable token body", func(srv **httptest.Server) http.HandlerFunc {
125				return func(w http.ResponseWriter, r *http.Request) {
126					if r.URL.Path == "/token" {
127						_, _ = w.Write([]byte("not json"))
128						return
129					}
130					w.Header().Set("Www-Authenticate", fmt.Sprintf(`Bearer realm="%s/token"`, (*srv).URL))
131					w.WriteHeader(http.StatusUnauthorized)
132				}
133			}},
134		}
135		for _, tt := range tests {
136			t.Run(tt.name, func(t *testing.T) {
137				var srv *httptest.Server
138				srv = httptest.NewServer(tt.handler(&srv))
139				defer srv.Close()
140	
141				_, err := ListRegistryTags(srv.URL, "library/alpine", "", "")
142				if err == nil {
143					t.Fatal("expected an error")
144				}
145				var se *StatusError
146				if errors.As(err, &se) {
147					t.Errorf("err = %v is a *StatusError, want a plain error", err)
148				}
149			})
150		}
151	}
