153	// A 401 received after a successful Bearer token exchange is a plain registry
154	// status, not an "unexpected auth challenge".
155	func TestListRegistryTags401AfterTokenExchange(t *testing.T) {
156		srv := bearerRegistry(t, okToken, func(w http.ResponseWriter, _ *http.Request) {
157			w.WriteHeader(http.StatusUnauthorized)
158		})
159		for name, list := range map[string]func() ([]string, error){
160			"plain":   func() ([]string, error) { return ListRegistryTags(srv.URL, "x", "", "") },
161			"context": func() ([]string, error) { return ListRegistryTagsContext(context.Background(), srv.URL, "x", "", "") },
162		} {
163			t.Run(name, func(t *testing.T) {
164				_, err := list()
165				var se *StatusError
166				if !errors.As(err, &se) {
167					t.Fatalf("err = %v (%T), want a *StatusError", err, err)
168				}
169				if se.Code != http.StatusUnauthorized || se.Source != SourceRegistry {
170					t.Errorf("got Code %d Source %v, want 401 SourceRegistry", se.Code, se.Source)
171				}
172				if got := err.Error(); got != "registry returned 401" {
173					t.Errorf("Error() = %q, want %q", got, "registry returned 401")
174				}
175			})
176		}
177	}
