1	package registrymgr
2	
3	import (
4		"bytes"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"log"
10		"net"
11		"net/http"
12		"net/http/httptest"
13		"strings"
14		"sync"
15		"testing"
16	
17		"github.com/anthnel/devdesk/internal/oci"
18	)
19	
20	// DEVDESK-412 step 6: the Nexus detector keeps its credentials on the origin they
21	// were meant for (a redirect to another origin is refused, the anonymous retry
22	// included) and bounds every response it reads. Server A is Nexus. The other
23	// origin is either server B (another port of the same host) or a sub-domain of
24	// A's host name; it answers with a group that has a member, so a redirect that
25	// was followed is visible in the result as well as in its log.
26	
27	const (
28		REDACTED = "user"
29		nexusTestPass = "S3CRETPW"
30		// The paths of the two Nexus endpoints the detector asks for.
31		nexusMetaPath   = "/service/rest/v1/repositories/docker-group"
32		nexusFormatPath = "/service/rest/v1/repositories/docker/group/docker-group"
33		// nexusLeakPath is where a redirect points; it must appear in no error.
34		nexusLeakPath = "/leak-target"
35		nexusSigned   = "sig=SECRET"
36		// nexusGroupNoMembers is the generic endpoint's answer for a group that
37		// does not list its members (the format endpoint is asked next).
38		nexusGroupNoMembers = `{"type":"group","format":"docker"}`
39		nexusGroupMembers   = `{"type":"group","format":"docker","group":{"memberNames":["a-proxy","b-hosted"]}}`
40		nexusLeakedMembers  = `{"type":"group","format":"docker","group":{"memberNames":["leaked"]}}`
41	)
42	
43	// nexusHits records every request a test server receives.
44	type nexusHits struct {
45		mu    sync.Mutex
46		paths []string
47		auths []string
48	}
49	
50	func (h *nexusHits) record(r *http.Request) {
51		h.mu.Lock()
52		defer h.mu.Unlock()
53		h.paths = append(h.paths, r.URL.RequestURI())
54		h.auths = append(h.auths, r.Header.Get("Authorization"))
55	}
56	
57	func (h *nexusHits) count() int {
58		h.mu.Lock()
59		defer h.mu.Unlock()
60		return len(h.paths)
61	}
62	
63	// authsFor returns the Authorization header of every request whose URI contains part.
64	func (h *nexusHits) authsFor(part string) []string {
65		h.mu.Lock()
66		defer h.mu.Unlock()
67		var out []string
68		for i, p := range h.paths {
69			if strings.Contains(p, part) {
70				out = append(out, h.auths[i])
71			}
72		}
73		return out
74	}
75	
76	func (h *nexusHits) anyAuth() string {
77		h.mu.Lock()
78		defer h.mu.Unlock()
79		for _, a := range h.auths {
80			if a != "" {
81				return a
82			}
83		}
84		return ""
85	}
86	
87	// nexusBasic is the Authorization header the detector sends for the test account.
88	func nexusBasic(t *testing.T) string {
89		t.Helper()
90		req, err := http.NewRequest(http.MethodGet, "http://x", nil)
91		if err != nil {
92			t.Fatal(err)
93		}
94		req.SetBasicAuth(REDACTED, nexusTestPass)
95		return req.Header.Get("Authorization")
96	}
97	
98	// nexusLog sends the standard logger to a buffer for the test and restores it.
99	func nexusLog(t *testing.T) *bytes.Buffer {
100		t.Helper()
101		var buf bytes.Buffer
102		old := log.Writer()
103		log.SetOutput(&buf)
104		t.Cleanup(func() { log.SetOutput(old) })
105		return &buf
106	}
107	
108	// dialTo sends every connection to addr whatever host name was asked for.
109	func dialTo(addr string) *http.Transport {
110		return &http.Transport{
111			DialContext: func(ctx context.Context, network, _ string) (net.Conn, error) {
112				var d net.Dialer
113				return d.DialContext(ctx, network, addr)
114			},
115		}
116	}
117	
118	// useNexusTransport swaps nexusHTTPClient for a copy of itself with another
119	// transport, so the redirect policy and the timeout of the production client
120	// stay in force.
121	func useNexusTransport(t *testing.T, rt http.RoundTripper) {
122		t.Helper()
123		old := nexusHTTPClient
124		c := *old
125		c.Transport = rt
126		nexusHTTPClient = &c
127		t.Cleanup(func() { nexusHTTPClient = old })
128	}
129	
130	// nexusEnv is one test setup: the registry's address, the logs of both origins
131	// and where a redirect has to point to leave the registry's origin.
132	type nexusEnv struct {
133		infoURL string // RegistryInfo.URL
134		other   string // base URL of the other origin
135		a, b    *nexusHits
136	}
137	
138	func (e *nexusEnv) info() RegistryInfo {
139		return RegistryInfo{Provider: ProviderNexus, URL: e.infoURL, Username: REDACTED, Password: nexusTestPass}
140	}
141	
142	// otherOrigins are the two ways a redirect leaves the origin.
143	var otherOrigins = []string{"other port", "sub-domain"}
144	
145	// startNexus starts Nexus (handler gets the base URL of the other origin) and the
146	// other origin, which answers every request with nexusLeakedMembers.
147	func startNexus(t *testing.T, kind string, handler func(w http.ResponseWriter, r *http.Request, other string)) *nexusEnv {
148		t.Helper()
149		env := &nexusEnv{a: &nexusHits{}, b: &nexusHits{}}
150		serveOther := func(w http.ResponseWriter, r *http.Request) {
151			env.b.record(r)
152			_, _ = io.WriteString(w, nexusLeakedMembers)
153		}
154	
155		switch kind {
156		case "other port":
157			b := httptest.NewServer(http.HandlerFunc(serveOther))
158			t.Cleanup(b.Close)
159			a := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
160				env.a.record(r)
161				handler(w, r, b.URL)
162			}))
163			t.Cleanup(a.Close)
164			env.infoURL, env.other = a.URL+"/repository/docker-group", b.URL
165		case "sub-domain":
166			// One listener answers both names; the Host tells them apart. They are
167			// two origins for net/http (and it would copy Authorization to the
168			// sub-domain).
169			var s *httptest.Server
170			s = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
171				if strings.HasPrefix(r.Host, "cdn.") {
172					serveOther(w, r)
173					return
174				}
175				env.a.record(r)
176				_, port, _ := net.SplitHostPort(s.Listener.Addr().String())
177				handler(w, r, "http://cdn.nexus.test:"+port)
178			}))
179			t.Cleanup(s.Close)
180			_, port, _ := net.SplitHostPort(s.Listener.Addr().String())
181			useNexusTransport(t, dialTo(s.Listener.Addr().String()))
182			env.infoURL, env.other = "http://nexus.test:"+port+"/repository/docker-group", "http://cdn.nexus.test:"+port
183		default:
184			t.Fatalf("unknown origin kind %q", kind)
185		}
186		return env
187	}
188	
189	// wantNoSecret fails when s (an error or a log) holds the password, the signed
190	// query or the path a redirect pointed to.
191	func wantNoSecret(t *testing.T, what, s string) {
192		t.Helper()
193		for _, leak := range []string{nexusTestPass, "SECRET", nexusSigned, nexusLeakPath} {
194			if strings.Contains(s, leak) {
195				t.Errorf("%s leaks %q: %s", what, leak, s)
196			}
197		}
198	}
199	
200	// 1. The generic endpoint redirected to another origin: refused, with the shared
201	// error of the other registry clients, and the credentials go nowhere.
202	func TestNexusMetaRedirectOffOriginIsRefused(t *testing.T) {
203		for _, kind := range otherOrigins {
204			t.Run(kind, func(t *testing.T) {
205				logs := nexusLog(t)
206				env := startNexus(t, kind, func(w http.ResponseWriter, r *http.Request, other string) {
207					http.Redirect(w, r, other+nexusLeakPath+"?"+nexusSigned, http.StatusTemporaryRedirect)
208				})
209	
210				members, err := (&NexusDetector{}).DetectGroup(context.Background(), env.info())
211	
212				if !errors.Is(err, oci.ErrOffOriginRedirect) {
213					t.Fatalf("err = %v, want errors.Is oci.ErrOffOriginRedirect (the manager could not be asked)", err)
214				}
215				if len(members) != 0 {
216					t.Errorf("members = %v, want none", members)
217				}
218				if n := env.b.count(); n != 0 {
219					t.Errorf("the other origin received %d requests, want 0", n)
220				}
221				if got := env.b.anyAuth(); got != "" {
222					t.Errorf("the other origin saw Authorization %q", got)
223				}
224				if got := env.a.authsFor(nexusMetaPath); len(got) != 1 || got[0] != nexusBasic(t) {
225					t.Errorf("Nexus Authorization headers = %q, want one Basic header", got)
226				}
227				wantNoSecret(t, "error", err.Error())
228				wantNoSecret(t, "log", logs.String())
229			})
230		}
231	}
232	
233	// 2. The format endpoint redirected to another origin: the refusal ends the
234	// detection. There is no anonymous retry after a refused redirect (the story puts
235	// a silent anonymous retry out of scope): Nexus sees one request with the
236	// credentials, the other origin none, and the log names the refusal without any
237	// signed path.
238	func TestNexusFormatEndpointRedirectOffOriginIsRefused(t *testing.T) {
239		for _, kind := range otherOrigins {
240			t.Run(kind, func(t *testing.T) {
241				logs := nexusLog(t)
242				env := startNexus(t, kind, func(w http.ResponseWriter, r *http.Request, other string) {
243					if !strings.Contains(r.URL.Path, "/group/") {
244						_, _ = io.WriteString(w, nexusGroupNoMembers)
245						return
246					}
247					http.Redirect(w, r, other+nexusLeakPath+"?"+nexusSigned, http.StatusTemporaryRedirect)
248				})
249	
250				members, err := (&NexusDetector{}).DetectGroup(context.Background(), env.info())
251	
252				if len(members) != 0 {
253					t.Errorf("members = %v, want none", members)
254				}
255				if err != nil && !errors.Is(err, oci.ErrOffOriginRedirect) {
256					t.Errorf("err = %v, want nil or errors.Is oci.ErrOffOriginRedirect", err)
257				}
258				if n := env.b.count(); n != 0 {
259					t.Errorf("the other origin received %d requests, want 0", n)
260				}
261				if got := env.a.authsFor("/group/"); len(got) != 1 || got[0] != nexusBasic(t) {
262					t.Errorf("Nexus saw Authorization %q on the format endpoint, want [Basic] only (no anonymous retry)", got)
263				}
264				if !strings.Contains(logs.String(), oci.ErrOffOriginRedirect.Error()) {
265					t.Errorf("the log does not mention the origin refusal: %s", logs.String())
266				}
267				wantNoSecret(t, "log", logs.String())
268				if err != nil {
269					wantNoSecret(t, "error", err.Error())
270				}
271			})
272		}
273	}
274	
275	// 2b. The anonymous retry stays for its own case: Nexus itself refuses the
276	// account (403) and answers the anonymous request.
277	func TestNexusAnonymousRetryAfterARefusedAccountStays(t *testing.T) {
278		env := startNexus(t, "other port", func(w http.ResponseWriter, r *http.Request, _ string) {
279			switch {
280			case !strings.Contains(r.URL.Path, "/group/"):
281				_, _ = io.WriteString(w, nexusGroupNoMembers)
282			case r.Header.Get("Authorization") != "":
283				w.WriteHeader(http.StatusForbidden)
284			default:
285				_, _ = io.WriteString(w, nexusGroupMembers)
286			}
287		})
288	
289		members, err := (&NexusDetector{}).DetectGroup(context.Background(), env.info())
290	
291		if err != nil {
292			t.Fatalf("DetectGroup: %v", err)
293		}
294		if len(members) != 2 {
295			t.Errorf("members = %v, want the 2 of the anonymous answer", members)
296		}
297		got := env.a.authsFor("/group/")
298		if len(got) != 2 || got[0] != nexusBasic(t) || got[1] != "" {
299			t.Errorf("Nexus saw Authorization %q on the format endpoint, want [Basic, none]", got)
300		}
301		if n := env.b.count(); n != 0 {
302			t.Errorf("the other origin received %d requests, want 0", n)
303		}
304	}
305	
306	// 3. A redirect that stays on Nexus is followed and keeps the credentials.
307	func TestNexusSameOriginRedirectIsFollowedWithCredentials(t *testing.T) {
308		cases := []struct {
309			name string
310			// generic is the generic endpoint's answer when it is not redirected:
311			// no members means the format endpoint is the one that gets redirected.
312			generic string
313			moved   string // path part of the second hop that must carry Authorization
314		}{
315			{"generic endpoint", nexusGroupMembers, "/moved-meta"},
316			{"format endpoint", nexusGroupNoMembers, "/moved-format"},
317		}
318		for _, tc := range cases {
319			t.Run(tc.name, func(t *testing.T) {
320				var s *httptest.Server
321				a := &nexusHits{}
322				s = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
323					a.record(r)
324					switch {
325					case strings.HasPrefix(r.URL.Path, "/moved-meta"):
326						_, _ = io.WriteString(w, nexusGroupMembers)
327					case strings.HasPrefix(r.URL.Path, "/moved-format"):
328						_, _ = io.WriteString(w, nexusGroupMembers)
329					case strings.Contains(r.URL.Path, "/group/"):
330						http.Redirect(w, r, "/moved-format", http.StatusFound)
331					default:
332						if tc.generic == nexusGroupMembers {
333							http.Redirect(w, r, "/moved-meta", http.StatusFound)
334							return
335						}
336						_, _ = io.WriteString(w, tc.generic)
337					}
338				}))
339				defer s.Close()
340				info := RegistryInfo{Provider: ProviderNexus, URL: s.URL + "/repository/docker-group", Username: REDACTED, Password: nexusTestPass}
341	
342				members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
343	
344				if err != nil {
345					t.Fatalf("DetectGroup: %v", err)
346				}
347				if len(members) != 2 {
348					t.Fatalf("members = %v, want the 2 of the redirected answer", members)
349				}
350				if got := a.authsFor(tc.moved); len(got) != 1 || got[0] != nexusBasic(t) {
351					t.Errorf("Authorization on %s = %q, want one Basic header", tc.moved, got)
352				}
353			})
354		}
355	}
356	
357	// 3 (anonymous retry). The authenticated request fails, the anonymous retry is
358	// redirected to another origin: that is refused too, and the retry itself carries
359	// no credential.
360	func TestNexusAnonymousRetryDoesNotFollowAnOffOriginRedirect(t *testing.T) {
361		for _, kind := range otherOrigins {
362			t.Run(kind, func(t *testing.T) {
363				logs := nexusLog(t)
364				env := startNexus(t, kind, func(w http.ResponseWriter, r *http.Request, other string) {
365					switch {
366					case !strings.Contains(r.URL.Path, "/group/"):
367						_, _ = io.WriteString(w, nexusGroupNoMembers)
368					case r.Header.Get("Authorization") != "":
369						// The account lacks the privilege: the retry starts.
370						w.WriteHeader(http.StatusForbidden)
371					default:
372						http.Redirect(w, r, other+nexusLeakPath+"?"+nexusSigned, http.StatusTemporaryRedirect)
373					}
374				})
375	
376				members, err := (&NexusDetector{}).DetectGroup(context.Background(), env.info())
377	
378				if err != nil {
379					t.Fatalf("err = %v, want nil", err)
380				}
381				if len(members) != 0 {
382					t.Errorf("members = %v, want none (the anonymous redirect was followed)", members)
383				}
384				if n := env.b.count(); n != 0 {
385					t.Errorf("the other origin received %d requests, want 0", n)
386				}
387				got := env.a.authsFor("/group/")
388				if len(got) != 2 || got[0] != nexusBasic(t) || got[1] != "" {
389					t.Errorf("Nexus saw Authorization %q on the format endpoint, want [Basic, none]", got)
390				}
391				wantNoSecret(t, "log", logs.String())
392			})
393		}
394	}
