396	// padded returns body followed by spaces up to exactly size bytes (valid JSON).
397	func padded(t *testing.T, body string, size int) string {
398		t.Helper()
399		if len(body) > size {
400			t.Fatalf("body (%d bytes) is longer than %d", len(body), size)
401		}
402		return body + strings.Repeat(" ", size-len(body))
403	}
