405	// writeBounded writes at most limit bytes of s and stops: no test server ever
406	// serves more than the few MiB a test asks for.
407	func writeBounded(w http.ResponseWriter, s string, limit int) {
408		if len(s) > limit {
409			s = s[:limit]
410		}
411		_, _ = io.WriteString(w, s)
412	}
