420	// 4. A response over the cap is an error, never a silent cut; one exactly at the
421	// cap is read. The oversized bodies start with a complete JSON document, so a
422	// reader that stopped at the cap would succeed.
423	func TestNexusResponseOverTheCapIsAnError(t *testing.T) {
424		const maxServed = 3 << 20 // no test server serves more than this
425	
426		t.Run("generic endpoint", func(t *testing.T) {
427			for _, tc := range []struct {
428				name string
429				size int
430				want error // nil = read
431			}{
432				{"exactly the cap", maxNexusResponse, nil},
433				{"one byte over", maxNexusResponse + 1, oci.ErrBodyTooLarge},
434				{"far over (2.5 MiB)", 5 << 19, oci.ErrBodyTooLarge},
435			} {
436				t.Run(tc.name, func(t *testing.T) {
437					body := padded(t, nexusGroupMembers, tc.size)
438					srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
439						writeBounded(w, body, maxServed)
440					}))
441					defer srv.Close()
442					info := RegistryInfo{Provider: ProviderNexus, URL: srv.URL + "/repository/docker-group", Username: REDACTED, Password: nexusTestPass}
443	
444					members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
445	
446					if tc.want == nil {
447						if err != nil || len(members) != 2 {
448							t.Fatalf("DetectGroup = %v, %v, want 2 members and no error", members, err)
449						}
450						return
451					}
452					if !errors.Is(err, tc.want) {
453						t.Fatalf("err = %v, want errors.Is %v", err, tc.want)
454					}
455					if len(members) != 0 {
456						t.Errorf("members = %v, want none (no silent cut)", members)
457					}
458					wantNoSecret(t, "error", err.Error())
459				})
460			}
461		})
462	
463		t.Run("format endpoint", func(t *testing.T) {
464			for _, tc := range []struct {
465				name string
466				size int
467				want int // members
468			}{
469				{"exactly the cap", maxNexusResponse, 2},
470				{"one byte over", maxNexusResponse + 1, 0},
471				{"far over (2.5 MiB)", 5 << 19, 0},
472			} {
473				t.Run(tc.name, func(t *testing.T) {
474					logs := nexusLog(t)
475					body := padded(t, nexusGroupMembers, tc.size)
476					srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
477						if !strings.Contains(r.URL.Path, "/group/") {
478							_, _ = io.WriteString(w, nexusGroupNoMembers)
479							return
480						}
481						writeBounded(w, body, maxServed)
482					}))
483					defer srv.Close()
484					info := RegistryInfo{Provider: ProviderNexus, URL: srv.URL + "/repository/docker-group", Username: REDACTED, Password: nexusTestPass}
485	
486					members, err := (&NexusDetector{}).DetectGroup(context.Background(), info)
487	
488					if err != nil {
489						t.Fatalf("err = %v, want nil (an unreadable format endpoint only means no members)", err)
490					}
491					if len(members) != tc.want {
492						t.Errorf("members = %d, want %d", len(members), tc.want)
493					}
494					if tc.want == 0 && !strings.Contains(logs.String(), "members unreachable") {
495						t.Errorf("an oversized answer left no trace in the log: %s", logs.String())
496					}
497					wantNoSecret(t, "log", logs.String())
498				})
499			}
500		})
501	}
